const distances=[25,50,75,100,200];
const hazard=c=>c>=5&&c<=9, remedy=c=>c>=10&&c<=14;
function choices(s){
 const i=s.seat;
 if(!s.drawn)return [{draw:true}];
 return s.hands[i].flatMap((c,index)=>{
  const out=[{discard:index}];
  if(c<5&&s.running[i]&&(!s.limited[i]||c<2)&&s.miles[i]+distances[c]<=1000&&(c!==4||s.large[i]<2))out.unshift({play:index});
  if(remedy(c)&&(c===14?s.limited[i]:c===13?!s.running[i]&&s.block[i]<0:s.block[i]===c-10))out.unshift({play:index});
  if(c>=15&&!s.safety[i].includes(c-15))out.unshift({play:index});
  if(hazard(c))for(let j=0;j<s.hands.length;j++)if(j!==i&&!s.safety[j].includes(c-5)&&(c===9?!s.limited[j]:s.running[j]))out.unshift({attack:[index,j]});
  return out;
 });
}
function finish(s,ctx){
 const high=Math.max(...s.miles);s.winners=s.miles.flatMap((v,i)=>v===high?[i]:[]);
 const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false),w=humans.filter(p=>s.winners.includes(ctx.players.indexOf(p))),paid=w.length?w:humans;
 return {state:s,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,Math.floor(ctx.pot/paid.length)+Number(i<ctx.pot%paid.length)]))};
}
const game={
 newMatch(ctx){
 const n=ctx.players.length,deck=[10,10,10,12,4,2,2,2,4,3,6,6,6,14,6,1,1,1,1].flatMap((q,c)=>Array(q).fill(c));
 let seed=2166136261;for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
 for(let i=deck.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}
 const hands=ctx.players.map(()=>deck.splice(0,6));
 const state={hands,stock:deck,miles:Array(n).fill(0),block:Array(n).fill(-1),running:Array(n).fill(false),limited:Array(n).fill(false),large:Array(n).fill(0),safety:hands.map(()=>[]),seat:0,drawn:false,winners:[]};
 return {state,turn:[ctx.players[0].id]};
 },
 applyMove(s,id,m,ctx){
 if(!m||s.winners.length||ctx.players[s.seat].id!==id||!choices(s).some(o=>JSON.stringify(o)===JSON.stringify(m)))throw new InvalidMove("Choose a legal move on your turn.");
 const i=s.seat,n=s.hands.length,state={...s,hands:s.hands.map(h=>[...h]),stock:[...s.stock],miles:[...s.miles],block:[...s.block],running:[...s.running],limited:[...s.limited],large:[...s.large],safety:s.safety.map(a=>[...a])};
 if(m.draw){if(!state.stock.length)return finish(state,ctx);state.hands[i].push(state.stock.shift());state.drawn=true;}
 else{
 const [c]=state.hands[i].splice(m.attack?m.attack[0]:m.play??m.discard,1);
 if(m.attack){const j=m.attack[1];if(c===9)state.limited[j]=true;else{state.running[j]=false;state.block[j]=c===8?-1:c-5;}}
 else if(m.play!==undefined){
 if(c<5){state.miles[i]+=distances[c];if(c===4)state.large[i]++;}
 else if(c===14)state.limited[i]=false;
 else if(c===13)state.running[i]=true;
 else if(c>=15){state.safety[i].push(c-15);if(state.block[i]===c-15)state.block[i]=-1;if(c===18){state.limited[i]=false;state.running[i]=state.block[i]<0;state.safety[i].push(4);}}
 else {state.block[i]=-1;if(state.safety[i].includes(3))state.running[i]=true;}
 }
 if(state.miles[i]===1000)return finish(state,ctx);
 state.seat=(i+1)%n;state.drawn=false;
 }
 return {state,turn:[ctx.players[state.seat].id]};
 },
 viewFor(s,id,ctx){const {hands,stock,...pub}=s,i=ctx.players.findIndex(p=>p.id===id);return {...pub,hand:hands[i]??[],choices:i===s.seat?choices(s):[]};},
 computerMove(s){const opts=choices(s);return opts.find(m=>m.play!==undefined)??opts.find(m=>m.attack)??opts[0];},
 randomMove(s,id,ctx){return this.computerMove(s);}
};

